WITH p AS (SELECT coalesce(%s::text,'') bom_code,coalesce(%s::text,'') product_code,coalesce(%s::text,'') trang_thai,%s::integer uid,%s::integer lim),s AS (SELECT p.*,u.user_id ok,coalesce(u.ds_branchs,'') bs,coalesce(u.is_super,0)=1 OR coalesce(u.ds_branchs,'')='' all_branch FROM p LEFT JOIN public.userinfo u ON u.user_id=p.uid) SELECT row_number() OVER(ORDER BY b.bom_code) stt,b.bom_code,b.product_code,v.ten_vt,b.bom_version,b.uom,b.product_quantity,b.routing_code,b.process_group_code,b.valid_from,b.valid_to,b.ma_ecn,b.ghi_chu,b.status,count(*) OVER() total FROM public.mfbom b LEFT JOIN public.dmvt v ON v.ma_vt=b.product_code CROSS JOIN s WHERE s.ok IS NOT NULL AND (s.bom_code='' OR b.bom_code=ANY(string_to_array(s.bom_code,','))) AND (s.product_code='' OR b.product_code=ANY(string_to_array(s.product_code,','))) AND (s.trang_thai='' OR b.status=s.trang_thai) AND (s.all_branch OR coalesce(b.branch_list,'')='' OR EXISTS(SELECT 1 FROM unnest(string_to_array(s.bs,',')) x WHERE x=ANY(string_to_array(b.branch_list,',')))) ORDER BY b.bom_code LIMIT (SELECT lim FROM p);
